function setStatus(message) {
  const el = document.getElementById("csvStatus");
  if (el) el.textContent = message;
}

window.addEventListener("error", event => {
  setStatus("JavaScript error: " + event.message);
});

function canonicalHeader(value) {
  return String(value || "")
    .replace(/^\uFEFF/, "")
    .trim()
    .toLowerCase()
    .replace(/[\s-]+/g, "_");
}

function parseCSV(text) {
  text = String(text || "").replace(/^\uFEFF/, "");
  const rows = [];
  let row = [], cell = "", inQuotes = false;

  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    const next = text[i + 1];

    if (char === '"' && inQuotes && next === '"') {
      cell += '"';
      i++;
    } else if (char === '"') {
      inQuotes = !inQuotes;
    } else if (char === "," && !inQuotes) {
      row.push(cell);
      cell = "";
    } else if ((char === "\n" || char === "\r") && !inQuotes) {
      if (char === "\r" && next === "\n") i++;
      row.push(cell);
      if (row.some(v => String(v).trim() !== "")) rows.push(row);
      row = [];
      cell = "";
    } else {
      cell += char;
    }
  }

  if (cell || row.length) {
    row.push(cell);
    if (row.some(v => String(v).trim() !== "")) rows.push(row);
  }

  if (!rows.length) return [];

  const rawHeaders = rows[0].map(h => h.trim());
  const headers = rawHeaders.map(canonicalHeader);
  const hasHeader = headers.some(h =>
    ["section_name", "section", "name", "title", "content", "section_content", "body", "text"].includes(h)
  );

  const bodyRows = hasHeader ? rows.slice(1) : rows;
  const useHeaders = hasHeader ? headers : ["section_name", "section_content", "default_include", "order", "audience", "variant_note"];

  return bodyRows.map((r, index) => {
    const obj = {};
    useHeaders.forEach((h, i) => obj[h] = (r[i] || "").trim());
    obj.__uid = `${index + 1}-${obj.section_name || obj.name || obj.title || obj.section || "section"}`;
    return normalizeSection(obj, index + 1);
  }).filter(s => s.sectionName && s.content);
}

function normalizeSection(row, index) {
  const sectionName =
    row.section_name ||
    row.name ||
    row.title ||
    row.section ||
    row.section_title ||
    `Section ${index}`;

  const content =
    row.section_content ||
    row.content ||
    row.body ||
    row.text ||
    row.copy ||
    "";

  const includeValue = String(row.default_include || row.include || "TRUE").toLowerCase();
  const order = Number(row.order || index);
  const audience = row.audience || "All";

  return {
    uid: row.__uid,
    order,
    sectionName,
    content,
    defaultInclude: includeValue !== "false" && includeValue !== "0" && includeValue !== "no",
    audience,
    variantNote: row.variant_note || row.notes || "",
  };
}

function escapeHtml(value) {
  return String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;");
}

function autoFormatText(text) {
  let safe = escapeHtml(text).trim();

  const makeLinksActive = document.getElementById("activeLinks")?.checked ?? true;
  const urlRegex = /(https?:\/\/[^\s<]+|(?:www\.)?[A-Za-z0-9.-]+\.(?:com|org|net|gov|biz|info)(?:\/[^\s<]*)?)/g;
  const phoneRegex = /(\d{1}[\.-]\d{3}[\.-]\d{3}[\.-]\d{4}|\d{3}[\.-]\d{3}[\.-]\d{4}|\d{1}-\d{3}-\d{3}-\d{4}|\d{3}-\d{3}-\d{4})/g;

  safe = safe
    .replace(/([.!?])\s+(?=[A-Z][A-Za-z0-9 &/()–—-]{2,90}:)/g, "$1\n\n")
    .replace(/;\s+(?=[A-Z][A-Za-z0-9 &/()–—-]{2,90}:)/g, ";\n\n");

  return safe.split(/\n{2,}/).map(chunk => {
    const colonIndex = chunk.indexOf(":");
    if (colonIndex > -1 && colonIndex <= 100) {
      chunk = '<span class="char-leadin">' + chunk.slice(0, colonIndex + 1) + '</span>' + chunk.slice(colonIndex + 1);
    }

    chunk = chunk.replace(urlRegex, m => {
      const href = m.startsWith("http://") || m.startsWith("https://") ? m : "https://" + m;
      return makeLinksActive
        ? `<a class="char-url" href="${href}" target="_blank" rel="noopener">${m}</a>`
        : `<span class="char-url">${m}</span>`;
    });

    chunk = chunk.replace(phoneRegex, m => '<span class="char-phone">' + m + '</span>');
    chunk = chunk.replace(/(ARBITRATION PREVENTS YOU FROM SUING SPARKLIGHT IN COURT OR FROM HAVING A JURY TRIAL\.?)/g, '<span class="char-legal-warning">$1</span>');
    return `<p class="p-leadin">${chunk}</p>`;
  }).join("");
}

function loadCSVText(text, label = "CSV") {
  const parsed = parseCSV(text);
  state.sections = parsed.sort((a, b) => a.order - b.order);
  state.selected = new Set(state.sections.filter(s => s.defaultInclude).map(s => s.uid));
  setStatus(`Loaded ${state.sections.length} sections from ${label}.`);
  if (!state.sections.length) {
    const list = document.getElementById("sectionList");
    if (list) list.innerHTML = '<div class="status">No sections parsed. Check CSV headers: section_name and section_content.</div>';
  }
  applyFilters();
}

async function tryRefreshFromExternalCSV() {
  try {
    const response = await fetch(state.csvFileName + "?v=" + Date.now(), { cache: "no-store" });
    if (!response.ok) return;
    const text = await response.text();
    const parsed = parseCSV(text);
    if (parsed.length) {
      loadCSVText(text, "IncludedSectionContent.csv");
    }
  } catch (err) {
    // No problem. Embedded bank already loaded.
  }
}

function loadSavedOrder() {
  try {
    const raw = localStorage.getItem(state.orderStorageKey);
    if (!raw) return;
    const obj = JSON.parse(raw);
    state.manualOrder = new Map(Object.entries(obj).map(([k, v]) => [k, Number(v)]));
  } catch (e) {
    state.manualOrder = new Map();
  }
}

function saveOrder() {
  const obj = {};
  state.manualOrder.forEach((v, k) => obj[k] = Number(v));
  localStorage.setItem(state.orderStorageKey, JSON.stringify(obj));
  setStatus("Manual order saved.");
}

function resetOrder() {
  state.manualOrder.clear();
  localStorage.removeItem(state.orderStorageKey);
  renderSectionControls();
  paginateDocument();
  setStatus("Manual order reset to CSV order.");
}

function getSelectedServices() {
  const preset = document.querySelector("input[name='titlePreset']:checked");
  if (preset && preset.value !== "custom") {
    return preset.value.split("+").map(s => s.trim()).filter(Boolean);
  }

  const checked = [...document.querySelectorAll("input[name='servicePart']:checked")]
    .sort((a, b) => Number(a.dataset.order) - Number(b.dataset.order))
    .map(i => i.value);

  return checked.length ? checked : ["Internet"];
}

function buildTitle() {
  const audience = document.getElementById("audience").value;
  const year = document.getElementById("year").value || "2026";
  const custom = document.getElementById("customTitle").value.trim();

  if (custom) return `${custom} ${year}`;
  return `${config[audience].audienceLabel} ${getSelectedServices().join(" + ")} ${year}`;
}

function applyTitleAndAudience() {
  const audience = document.getElementById("audience").value;
  const c = config[audience];
  const title = buildTitle();

  document.querySelectorAll("[data-bind='phone']").forEach(el => el.textContent = c.phone);
  document.querySelectorAll("[data-bind='website']").forEach(el => el.textContent = c.website);
  document.querySelectorAll("[data-bind='doc-title']").forEach(el => el.textContent = title);
  document.querySelectorAll("[data-bind='footer-title']").forEach(el => el.textContent = `Annual Notice ${title}`);

  const preview = document.getElementById("titlePreview");
  if (preview) preview.textContent = title;

  applyFilters();
}

function stableSectionKey(section) {
  return section.uid;
}

function getEffectiveOrder(section) {
  return state.manualOrder.has(stableSectionKey(section))
    ? Number(state.manualOrder.get(stableSectionKey(section)))
    : Number(section.order || 9999);
}

function sortSectionsForOutput(list) {
  return [...list].sort((a, b) => {
    const diff = getEffectiveOrder(a) - getEffectiveOrder(b);
    if (diff !== 0) return diff;
    return (a.order || 0) - (b.order || 0);
  });
}

function applyFilters() {
  const audience = document.getElementById("audience").value.toLowerCase();
  const search = document.getElementById("sectionSearch").value.toLowerCase().trim();

  state.filtered = state.sections.filter(s => {
    const audienceValue = String(s.audience || "all").toLowerCase();
    const audienceMatch = audienceValue === "all" || audienceValue === "" || audienceValue.includes(audience);
    const searchMatch = !search || s.sectionName.toLowerCase().includes(search) || s.content.toLowerCase().includes(search);
    return audienceMatch && searchMatch;
  });

  renderSectionControls();
  paginateDocument();
}

function renderSectionControls() {
  const list = document.getElementById("sectionList");
  const orderedFiltered = sortSectionsForOutput(state.filtered);

  list.innerHTML = orderedFiltered.map(s => `
    <label class="section-item" draggable="true" data-uid="${escapeHtml(s.uid)}">
      <input type="checkbox" data-uid="${escapeHtml(s.uid)}" ${state.selected.has(s.uid) ? "checked" : ""}>
      <span>
        <span class="section-item-title">${escapeHtml(s.sectionName)}</span>
        <span class="section-item-meta">CSV Order ${s.order} · ${escapeHtml(s.audience || "All")}${s.variantNote ? " · " + escapeHtml(s.variantNote) : ""}</span>
        <span class="section-actions">
          <span class="drag-handle" title="Drag to reorder">☰</span>
          <span class="section-item-meta">Manual order</span>
          <input type="number" class="order-input" data-order-uid="${escapeHtml(s.uid)}" value="${getEffectiveOrder(s)}" min="1" step="1">
        </span>
      </span>
    </label>
  `).join("");

  list.querySelectorAll("input[type='checkbox']").forEach(input => {
    input.addEventListener("change", e => {
      if (e.target.checked) state.selected.add(e.target.dataset.uid);
      else state.selected.delete(e.target.dataset.uid);
      paginateDocument();
    });
  });

  list.querySelectorAll(".order-input").forEach(input => {
    input.addEventListener("change", e => {
      const uid = e.target.dataset.orderUid;
      const value = Number(e.target.value);
      if (Number.isFinite(value)) state.manualOrder.set(uid, value);
      renderSectionControls();
      paginateDocument();
    });
  });

  setupDragOrdering(list);
}

function setupDragOrdering(list) {
  let draggedUid = null;

  list.querySelectorAll(".section-item").forEach(item => {
    item.addEventListener("dragstart", e => {
      draggedUid = item.dataset.uid;
      item.classList.add("dragging");
      e.dataTransfer.effectAllowed = "move";
    });

    item.addEventListener("dragend", () => {
      draggedUid = null;
      list.querySelectorAll(".section-item").forEach(i => i.classList.remove("dragging", "drag-over"));
    });

    item.addEventListener("dragover", e => {
      e.preventDefault();
      if (item.dataset.uid !== draggedUid) item.classList.add("drag-over");
    });

    item.addEventListener("dragleave", () => item.classList.remove("drag-over"));

    item.addEventListener("drop", e => {
      e.preventDefault();
      item.classList.remove("drag-over");
      if (!draggedUid || draggedUid === item.dataset.uid) return;

      const visible = sortSectionsForOutput(state.filtered);
      const fromIndex = visible.findIndex(s => s.uid === draggedUid);
      const toIndex = visible.findIndex(s => s.uid === item.dataset.uid);
      if (fromIndex < 0 || toIndex < 0) return;

      const moved = visible.splice(fromIndex, 1)[0];
      visible.splice(toIndex, 0, moved);
      visible.forEach((s, i) => state.manualOrder.set(s.uid, i + 1));

      renderSectionControls();
      paginateDocument();
    });
  });
}

function selectedSectionsHtmlArray() {
  return sortSectionsForOutput(state.sections.filter(s => state.selected.has(s.uid)))
    .map(s => `
      <section class="legal-section" data-section-name="${escapeHtml(s.sectionName)}">
        <h2 class="h2-section">${escapeHtml(s.sectionName)}</h2>
        ${autoFormatText(s.content)}
      </section>
    `);
}

function createPage(pageNumber) {
  const template = document.getElementById("pageTemplate");
  const page = template.cloneNode(true);
  page.id = "";
  page.hidden = false;
  page.removeAttribute("hidden");
  page.classList.add("generated-page");
  page.querySelectorAll("[id]").forEach(el => el.removeAttribute("id"));

  const audience = document.getElementById("audience").value;
  const c = config[audience];
  const title = buildTitle();
  const logo = page.querySelector(".logo");
  if (logo) logo.src = c.logo;

  page.querySelectorAll("[data-bind='phone']").forEach(el => el.textContent = c.phone);
  page.querySelectorAll("[data-bind='website']").forEach(el => el.textContent = c.website);
  page.querySelectorAll("[data-bind='doc-title']").forEach(el => el.textContent = title);
  page.querySelectorAll("[data-bind='footer-title']").forEach(el => el.textContent = `Annual Notice ${title}`);
  return page;
}

function contentOverflows(contentEl) {
  return contentEl.scrollHeight > contentEl.clientHeight + 2 || contentEl.scrollWidth > contentEl.clientWidth + 2;
}

function applyColumnsToContent(contentEl) {
  const setting = document.getElementById("columns").value;
  contentEl.classList.remove("layout-1col", "layout-2col");

  if (setting === "1") contentEl.classList.add("layout-1col");
  else if (setting === "2") contentEl.classList.add("layout-2col");
  else {
    const textLength = contentEl.innerText.replace(/\s+/g, " ").trim().length;
    const blockCount = contentEl.querySelectorAll("p, li, h2").length;
    if (textLength < 2600 || blockCount < 18) contentEl.classList.add("layout-1col");
    else contentEl.classList.add("layout-2col");
  }
}

function splitOversizeSection(sectionHtml, targetPageContent, makeNewPage) {
  const temp = document.createElement("div");
  temp.innerHTML = sectionHtml;
  const section = temp.firstElementChild;
  const title = section.querySelector(".h2-section")?.outerHTML || "";
  const chunks = [...section.querySelectorAll("p, ul, ol")].map(el => el.outerHTML);

  let currentContent = targetPageContent;
  let sectionOpen = null;

  function ensureSection(openTitle) {
    if (!sectionOpen) {
      const wrap = document.createElement("section");
      wrap.className = "legal-section";
      if (openTitle) wrap.insertAdjacentHTML("beforeend", title);
      currentContent.appendChild(wrap);
      sectionOpen = wrap;
    }
    return sectionOpen;
  }

  chunks.forEach((chunk, index) => {
    const wrap = ensureSection(index === 0);
    wrap.insertAdjacentHTML("beforeend", chunk);

    if (contentOverflows(currentContent)) {
      wrap.lastElementChild.remove();
      const newPage = makeNewPage();
      currentContent = newPage.querySelector(".document-content");
      applyColumnsToContent(currentContent);
      sectionOpen = null;
      const newWrap = ensureSection(index === 0);
      newWrap.insertAdjacentHTML("beforeend", chunk);
    }
  });

  return currentContent;
}

function renderAttachmentControls() {
  const list = document.getElementById("attachmentList");
  if (!list) return;

  if (!state.attachments.length) {
    list.innerHTML = '<div class="status">No attachments added.</div>';
    return;
  }

  list.innerHTML = state.attachments.map((att, index) => `
    <div class="attachment-item">
      <span>${index + 1}. ${escapeHtml(att.name)}</span>
      <button type="button" class="secondary" data-remove-attachment="${index}">Remove</button>
    </div>
  `).join("");

  list.querySelectorAll("[data-remove-attachment]").forEach(btn => {
    btn.addEventListener("click", e => {
      const index = Number(e.target.dataset.removeAttachment);
      const att = state.attachments[index];
      if (att && att.url) URL.revokeObjectURL(att.url);
      state.attachments.splice(index, 1);
      renderAttachmentControls();
      paginateDocument();
    });
  });
}

function appendAttachmentPages(preview, pages) {
  state.attachments.forEach((att, index) => {
    const page = createPage(pages.length + 1);
    page.classList.add("attachment-page");
    const content = page.querySelector(".document-content");
    content.classList.remove("layout-1col", "layout-2col");
    content.innerHTML = `
      <p class="attachment-note">Attachment ${index + 1}: ${escapeHtml(att.name)}</p>
      <object class="pdf-attachment-object" data="${att.url}" type="application/pdf">
        <iframe class="pdf-attachment-frame" src="${att.url}" title="${escapeHtml(att.name)}"></iframe>
      </object>
    `;
    preview.appendChild(page);
    pages.push(page);
  });
}

function parsePx(value) {
  const n = Number(String(value || "").replace("px", ""));
  return Number.isFinite(n) ? n : 0;
}

function estimateLineHeightPx(element) {
  const style = window.getComputedStyle(element);
  const lh = parsePx(style.lineHeight);
  if (lh > 0) return lh;
  const fs = parsePx(style.fontSize);
  return fs ? fs * 1.2 : 12;
}

function minimumSectionStartHeightPx(contentEl, sectionEl) {
  const heading = sectionEl.querySelector(".h2-section");
  const firstPara = sectionEl.querySelector("p, li");
  const headingHeight = heading ? heading.getBoundingClientRect().height : 0;
  const lineHeight = firstPara ? estimateLineHeightPx(firstPara) : estimateLineHeightPx(contentEl);

  // Rule: if the section header plus fewer than 3 lines of body can fit,
  // move the whole section to the next page.
  return headingHeight + (lineHeight * 3);
}

function shouldMoveSectionToNextPage(contentEl, sectionEl) {
  const available = contentEl.clientHeight - contentEl.scrollTop - contentEl.scrollHeight;
  const minNeeded = minimumSectionStartHeightPx(contentEl, sectionEl);

  // If section starts near the bottom and only a stub would fit, jump it.
  return available > 0 && available < minNeeded;
}

function lastSectionHasOnlyStub(contentEl) {
  const section = contentEl.lastElementChild;
  if (!section || !section.classList.contains("legal-section")) return false;

  const contentRect = contentEl.getBoundingClientRect();
  const sectionRect = section.getBoundingClientRect();
  const firstPara = section.querySelector("p, li");
  const lineHeight = firstPara ? estimateLineHeightPx(firstPara) : estimateLineHeightPx(contentEl);
  const visibleHeight = Math.max(0, contentRect.bottom - sectionRect.top);

  return visibleHeight > 0 && visibleHeight < minimumSectionStartHeightPx(contentEl, section);
}

function paginateDocument() {
  const preview = document.getElementById("previewPages");
  preview.innerHTML = "";

  const sections = selectedSectionsHtmlArray();
  const pages = [];
  let pageNumber = 1;

  function makeNewPage() {
    const page = createPage(pageNumber++);
    preview.appendChild(page);
    pages.push(page);
    const content = page.querySelector(".document-content");
    applyColumnsToContent(content);
    return page;
  }

  let page = makeNewPage();
  let content = page.querySelector(".document-content");

  sections.forEach(sectionHtml => {
    content.insertAdjacentHTML("beforeend", sectionHtml);

    // Keep-with-next rule:
    // If the section starts at the bottom with less than heading + 3 body lines visible,
    // move the whole section to the next page before normal overflow handling.
    if (!contentOverflows(content) && lastSectionHasOnlyStub(content)) {
      const added = content.lastElementChild;
      added.remove();

      const newPage = makeNewPage();
      content = newPage.querySelector(".document-content");
      content.insertAdjacentHTML("beforeend", sectionHtml);
    }

    if (contentOverflows(content)) {
      const added = content.lastElementChild;
      added.remove();

      const testPage = makeNewPage();
      const testContent = testPage.querySelector(".document-content");
      testContent.insertAdjacentHTML("beforeend", sectionHtml);

      if (contentOverflows(testContent)) {
        testContent.innerHTML = "";
        content = splitOversizeSection(sectionHtml, testContent, makeNewPage);
      } else {
        content = testContent;
      }
    }
  });

  appendAttachmentPages(preview, pages);

  pages.forEach((p, i) => {
    const marker = p.querySelector(".page-marker");
    if (marker) marker.textContent = `Page ${i + 1} of ${pages.length}`;
  });

  document.getElementById("selectedCount").textContent = `${state.selected.size} selected · ${pages.length} page${pages.length === 1 ? "" : "s"}`;
}

function selectAllVisible(value) {
  state.filtered.forEach(s => {
    if (value) state.selected.add(s.uid);
    else state.selected.delete(s.uid);
  });
  renderSectionControls();
  paginateDocument();
}

function wireEvents() {
  document.getElementById("csvUpload").addEventListener("change", e => {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => loadCSVText(reader.result, file.name);
    reader.readAsText(file);
  });

  document.getElementById("audience").addEventListener("change", applyTitleAndAudience);
  document.getElementById("year").addEventListener("input", applyTitleAndAudience);
  document.getElementById("columns").addEventListener("change", paginateDocument);
  document.getElementById("sectionSearch").addEventListener("input", applyFilters);
  document.getElementById("customTitle").addEventListener("input", applyTitleAndAudience);
  document.getElementById("selectAllVisible").addEventListener("click", () => selectAllVisible(true));
  document.getElementById("clearVisible").addEventListener("click", () => selectAllVisible(false));
  document.getElementById("saveOrder").addEventListener("click", saveOrder);
  document.getElementById("resetOrder").addEventListener("click", resetOrder);
  document.getElementById("activeLinks").addEventListener("change", paginateDocument);

  document.getElementById("attachmentUpload").addEventListener("change", e => {
    [...e.target.files].forEach(file => {
      if (file.type === "application/pdf" || file.name.toLowerCase().endsWith(".pdf")) {
        state.attachments.push({ name: file.name, file, url: URL.createObjectURL(file) });
      }
    });
    e.target.value = "";
    renderAttachmentControls();
    paginateDocument();
  });

  document.querySelectorAll("input[name='servicePart'], input[name='titlePreset']").forEach(input => {
    input.addEventListener("change", () => {
      if (input.name === "servicePart") {
        document.querySelector("input[name='titlePreset'][value='custom']").checked = true;
      }
      applyTitleAndAudience();
    });
  });
}

document.addEventListener("DOMContentLoaded", () => {
  wireEvents();
  loadSavedOrder();
  renderAttachmentControls();

  // Load embedded bank immediately so GitHub Pages/local file loading cannot leave the app blank.
  loadCSVText(EMBEDDED_INCLUDED_SECTION_CONTENT_CSV, "embedded section bank");

  // Then refresh from external CSV if GitHub Pages serves it correctly.
  tryRefreshFromExternalCSV();
});
